func _tick_level2(delta: float, ppos: Vector3) -> void:
	if String(g.get("phase", "")) == "promenade":
		_companion_ref().tick_canvas_care(delta)
		_lagoon_promenade_ref().tick(delta)
		return
	_lagoon_ref()._tick_level2(delta, ppos)

